// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns



// EVOLVE-BLOCK-START
// Initial implementation: Simple quicksort
// This can be evolved to:
// - Hybrid algorithms (introsort, timsort-like)
// - Adaptive pivot selection
// - Special handling for nearly sorted data
// - Switching to different algorithms based on data characteristics

pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    if len <= 32 { insertion_sort(arr); return; }
    // Check if nearly sorted: count adjacent inversions
    let mut inv = 0usize;
    for i in 0..len - 1 {
        if arr[i] > arr[i + 1] { inv += 1; }
    }
    if inv <= len / 8 { insertion_sort(arr); return; }
    let depth = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, 0, len - 1, depth);
}

fn introsort<T: Ord>(arr: &mut [T], mut low: usize, mut high: usize, mut depth: usize) {
    while high > low {
        let len = high - low + 1;
        if len <= 24 { insertion_sort(&mut arr[low..=high]); return; }
        if depth == 0 { heapsort(&mut arr[low..=high]); return; }
        depth -= 1;

        let p = partition(arr, low, high);
        // Recurse on smaller side, loop on larger side.
        if p > 0 && (p - low) < (high - p) {
            introsort(arr, low, p - 1, depth);
            low = p + 1;
        } else {
            if p + 1 <= high { introsort(arr, p + 1, high, depth); }
            if p == 0 { return; }
            high = p - 1;
        }
    }
}

fn partition<T: Ord>(arr: &mut [T], low: usize, high: usize) -> usize {
    // Median-of-three pivot, moved to `high`
    let mid = low + (high - low) / 2;
    if arr[low] > arr[mid] { arr.swap(low, mid); }
    if arr[low] > arr[high] { arr.swap(low, high); }
    if arr[mid] > arr[high] { arr.swap(mid, high); }
    arr.swap(mid, high);

    let mut i = low;
    for j in low..high {
        if arr[j] <= arr[high] { arr.swap(i, j); i += 1; }
    }
    arr.swap(i, high);
    i
}

fn heapsort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    for i in (0..n / 2).rev() { sift_down(arr, i, n); }
    for i in (1..n).rev() { arr.swap(0, i); sift_down(arr, 0, i); }
}

fn sift_down<T: Ord>(arr: &mut [T], mut root: usize, end: usize) {
    loop {
        let mut child = 2 * root + 1;
        if child >= end { break; }
        if child + 1 < end && arr[child] < arr[child + 1] { child += 1; }
        if arr[root] >= arr[child] { break; }
        arr.swap(root, child);
        root = child;
    }
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] { arr.swap(j, j - 1); j -= 1; }
    }
}
